const listStatusesOfHookDecisions = `-- name: ListStatusesOfHookDecisions :many
SELECT decision_id, status_id FROM hook_decision_statuses WHERE decision_id IN (/*SLICE:ids*/?) ORDER BY decision_id, status_id
`

func (q *Queries) ListStatusesOfHookDecisions(ctx context.Context, ids []string) ([]HookDecisionStatus, error) {
	query := listStatusesOfHookDecisions
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []HookDecisionStatus{}
	for rows.Next() {
		var i HookDecisionStatus
		if err := rows.Scan(&i.DecisionID, &i.StatusID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const summarizeHookDecisions = `-- name: SummarizeHookDecisions :many
SELECT hook, mode, outcome, COUNT(*) AS decisions,
  CAST(COALESCE(SUM(latency_ms), 0) AS INTEGER) AS total_latency_ms,
  CAST(COALESCE(MAX(latency_ms), 0) AS INTEGER) AS max_latency_ms
FROM hook_decisions
WHERE decided_at >= ?
GROUP BY hook, mode, outcome
ORDER BY hook, mode, outcome
`

type SummarizeHookDecisionsRow struct {
	Hook           string
	Mode           string
	Outcome        string
	Decisions      int64
	TotalLatencyMs int64
	MaxLatencyMs   int64
}

func (q *Queries) SummarizeHookDecisions(ctx context.Context, decidedAt int64) ([]SummarizeHookDecisionsRow, error) {
	rows, err := q.db.QueryContext(ctx, summarizeHookDecisions, decidedAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummarizeHookDecisionsRow{}
	for rows.Next() {
		var i SummarizeHookDecisionsRow
		if err := rows.Scan(
			&i.Hook,
			&i.Mode,
			&i.Outcome,
			&i.Decisions,
			&i.TotalLatencyMs,
			&i.MaxLatencyMs,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
